14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const BASE_PREMIUM_BY_ITEM_TYPE = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	} as const satisfies Record<string, number>;
53	
54	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
55	
56	const basePremiumOf = (item: Item): number =>
57	  BASE_PREMIUM_BY_ITEM_TYPE[item.type as InsurableItemType];
58	
59	const sumBasePremiums = (items: Item[]): number =>
60	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
61	
62	const quotePremium = (items: Item[]): number => {
63	  const policyBase = sumBasePremiums(items);
64	  const premiumBeforeFee =
65	    policyBase + percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
66	  return Math.ceil(premiumBeforeFee + PROCESSING_FEE);
67	};
68	
69	const runStep = (step: Step): StepResult => {
70	  if (step.op === "quote") return { premium: quotePremium(step.items) };
71	  throw new Error("claim steps are not implemented yet");
72	};
73	
74	export const runScenario = (scenario: Scenario): ScenarioResult => ({
75	  results: scenario.steps.map(runStep),
76	});
